const telegramData = $('Kiểm Tra Loại Message').item.json;
const userMessage = (telegramData.message.text || '').trim();
const chatId = telegramData.message.chat.id;
const userName = telegramData.message.from.first_name || 'Bạn';

const allItems = $input.all();
const products = [];
const faqs = [];

for (const item of allItems) {
 const resp = item.json;
 const dataArr = resp.data || resp;
 const rows = Array.isArray(dataArr) ? dataArr : [dataArr];

 for (const row of rows) {
   if (row.id && row.name && row.price !== undefined) {
     products.push({
       id: String(row.id || ''),
       name: (row.name || '').toLowerCase(),
       name_orig: row.name || '',
       brand: (row.brand || '').toLowerCase(),
       brand_orig: row.brand || '',
       sport: row.sport || '',
       category: row.category || '',
       price: Number(row.price || 0),
       description: row.description || '',
       stock: row.stockStatus || 'Không rõ',
     });
   }
   if (row.topic && row.answer) {
     faqs.push({
       topic: row.topic || '',
       keywords: (row.questionKeywords || '').toLowerCase(),
       answer: row.answer || '',
     });
   }
 }
}

const msg = userMessage.toLowerCase();
const INTENT_MAP = [
 ['exchange', ['đổi hàng', 'trả hàng', 'hoàn tiền', 'đổi size', 'đổi trả', 'đổi', 'trả', 'hoàn']],
 ['shipping', ['phí ship', 'giao hàng', 'vận chuyển', 'thời gian giao', 'ship', 'bao lâu']],
 ['payment', ['thanh toán', 'trả tiền', 'cod', 'chuyển khoản', 'momo', 'zalopay', 'zalo', 'thẻ']],
 ['warranty', ['bảo hành', 'hàng lỗi', 'lỗi hàng', 'bảo hành mấy tháng']],
 ['stock', ['còn hàng', 'còn không', 'hết hàng', 'có hàng', 'tồn kho', 'còn size', 'hết size']],
 ['compare', ['so sánh', 'khác nhau', 'tốt hơn', 'nên chọn', 'hay là']],
 ['describe', ['mô tả', 'giới thiệu', 'thông tin', 'chi tiết', 'công nghệ', 'chất liệu', 'tính năng']],
 ['brand', ['hãng nào', 'thương hiệu', 'của ai', 'sản xuất', 'nhà sản xuất']],
 ['size', ['bảng size', 'size áo', 'size giày', 'cỡ áo', 'cỡ giày', 'số giày', 'form', 'chọn size']],
 ['price', ['giá bao nhiêu', 'bao nhiêu tiền', 'giá', 'bao nhiêu', 'tiền']],
 ['order_tracking', ['tra cứu', 'đơn hàng', 'kiểm tra đơn', 'xem đơn', 'tình trạng đơn', 'mã đơn', 'đơn của tôi', 'đơn của mình']],
];

let intent = 'general';
for (const [key, kws] of INTENT_MAP) {
 if (kws.some(k => msg.includes(k))) { intent = key; break; }
}

const POLICY_INTENTS = ['exchange','size','shipping','payment','warranty'];
const isPolicy = POLICY_INTENTS.includes(intent);

const STOP = new Set(['của','và','có','không','cho','bao','nhiêu','giá','còn','thì','sao','muốn','mua','cái','chiếc','đôi','như','nào','rồi','này','đó','là','gì','với','anh','chị','em','shop','ạ','nhé']);
const tokens = msg.replace(/[?,!.]/g,' ').split(/\s+/).filter(t => t.length > 1 && !STOP.has(t));

function scoreProduct(p) {
 let score = 0;
 for (const tok of tokens) {
   if (p.name.includes(tok)) score += 10;
   if (p.brand.includes(tok)) score += 8;
   if (p.category.toLowerCase().includes(tok)) score += 5;
   if (p.sport.toLowerCase().includes(tok)) score += 4;
   if (p.description.toLowerCase().includes(tok)) score += 1;
 }
 return score;
}

function scoreFaq(f) {
 let score = 0;
 for (const tok of tokens) {
   if (f.keywords.includes(tok)) score += 10;
   if (f.topic.toLowerCase().includes(tok)) score += 5;
   if (f.answer.toLowerCase().includes(tok)) score += 1;
 }
 return score;
}

let filteredProducts = products.map(p => ({ ...p, score: scoreProduct(p) })).filter(p => p.score > 0).sort((a, b) => b.score - a.score);
let filteredFaqs = faqs.map(f => ({ ...f, score: scoreFaq(f) })).filter(f => f.score > 0).sort((a, b) => b.score - a.score);

let maxProducts = (intent === 'compare') ? 4 : 3;

if (filteredProducts.length === 0 && tokens.length === 0 && intent === 'general') {
    filteredProducts = products.slice(0, 3);
} else {
    filteredProducts = filteredProducts.slice(0, maxProducts);
}

if (filteredFaqs.length === 0 && isPolicy) {
    let fallbackFaqs = faqs.filter(f => f.topic.toLowerCase().includes(intent));
    if(fallbackFaqs.length > 0) filteredFaqs = fallbackFaqs.slice(0, 3);
    else filteredFaqs = faqs.slice(0, 3);
} else {
    filteredFaqs = filteredFaqs.slice(0, 3);
}

function sanitize(str) {
 return String(str).replace(/[\r\n\t]/g, ' ').replace(/[\x00-\x1F\x7F]/g, ' ').trim();
}

let productContext = '';
for (const p of filteredProducts) {
 productContext += `- [${p.id}] ${p.name_orig} | Hãng: ${p.brand_orig} | Giá: ${p.price.toLocaleString('vi-VN')} VNĐ | Tình trạng: ${p.stock}\n`;
}

let faqContext = '';
for (const f of filteredFaqs) {
 faqContext += `- [${f.topic}] ${f.answer}\n`;
}

// ==== EXTRACT ORDER INFO ====
let msgForId = userMessage;
let orderPhone = null;
let orderId = null;

// Tìm và chuẩn hóa phone (cho phép có dấu cách/chấm/gạch nối)
const phoneRegex = /(03|05|07|08|09)[\s\.-]?\d{3}[\s\.-]?\d{3,4}/;
const pMatch = userMessage.match(phoneRegex);
if (pMatch) {
    // Xóa số điện thoại ra khỏi câu để khi tìm ID không bị nhầm
    msgForId = userMessage.replace(pMatch[0], '');
    orderPhone = pMatch[0].replace(/[\s\.-]/g, '');
}

const idMatch = msgForId.match(/\d+/g);
if (idMatch) {
    orderId = idMatch[0]; // Lấy số đầu tiên còn lại làm ID đơn hàng
}

return [{
 json: {
   chatId,
   userName: sanitize(userName),
   userMessage: sanitize(userMessage),
   intent,
   isPolicy,
   productContext: sanitize(productContext) || 'Không tìm thấy sản phẩm phù hợp',
   faqContext: sanitize(faqContext) || 'Không có FAQ phù hợp',
   orderPhone,
   orderId,
   needOrderFetch: !!(orderPhone && orderId && intent === 'order_tracking'),
   timestamp: new Date().toISOString(),
 }
}];

const ctx = $('Smart Filter + Intent').item.json;
let orderDataStr = '';

if (ctx.needOrderFetch) {
  try {
    const orderResp = $('Lấy Dữ Liệu Đơn Hàng').item.json;
    if (orderResp.success && orderResp.data) {
      const d = orderResp.data;
      orderDataStr = `Trạng thái: ${d.status} | Tổng tiền: ${d.totalMoney.toLocaleString('vi-VN')} VNĐ | Thanh toán: ${d.paymentMethod} | SP: ${d.items.join(', ')}`;
    } else {
      orderDataStr = orderResp.message || 'Không tìm thấy đơn hàng với thông tin đã cung cấp.';
    }
  } catch(e) {
    orderDataStr = 'Lỗi hệ thống khi tra cứu đơn hàng.';
  }
}

// Đọc memory
let conversationHistory = [];
try {
 const memItems = $('Load Memory').all();
 if (memItems.length > 0 && memItems[0].json.history_json) {
  conversationHistory = JSON.parse(memItems[0].json.history_json);
 }
} catch(e) {
 conversationHistory = [];
}
conversationHistory = conversationHistory.slice(-5);

let historyStr = '';
if (conversationHistory.length > 0) {
 historyStr = '[LỊCH SỬ HỘI THOẠI GẦN ĐÂY]\n';
 for (const turn of conversationHistory) {
  historyStr += `Khách: ${turn.user}\nTư vấn viên: ${turn.bot}\n`;
 }
 historyStr += '\n';
}

let dataBlock = '';
let hasProduct = ctx.productContext !== 'Không tìm thấy sản phẩm phù hợp';
let hasFaq = ctx.faqContext !== 'Không có FAQ phù hợp';

if (hasProduct) dataBlock += `[SẢN PHẨM]\n${ctx.productContext}\n`;
if (hasFaq) dataBlock += `[CHÍNH SÁCH]\n${ctx.faqContext}\n`;
if (orderDataStr) dataBlock += `[THÔNG TIN ĐƠN HÀNG TRA CỨU ĐƯỢC]\n${orderDataStr}\n`;

const intentGuide = {
 stock: 'Thông báo tình trạng tồn kho từ [SẢN PHẨM].',
 price: 'Nêu giá sản phẩm từ [SẢN PHẨM].',
 describe: 'Mô tả sản phẩm từ [SẢN PHẨM].',
 brand: 'Xác nhận thương hiệu từ [SẢN PHẨM].',
 exchange: 'Trả lời dựa nội dung [CHÍNH SÁCH] mục đổi trả.',
 size: 'Trả lời dựa nội dung [CHÍNH SÁCH] mục size.',
 shipping: 'Trả lời dựa nội dung [CHÍNH SÁCH] mục vận chuyển.',
 payment: 'Trả lời dựa nội dung [CHÍNH SÁCH] mục thanh toán.',
 warranty: 'Trả lời dựa nội dung [CHÍNH SÁCH] mục bảo hành.',
 compare: 'So sánh các sản phẩm trong [SẢN PHẨM].',
 order_tracking: orderDataStr ? 'Thông báo tình trạng đơn hàng trong [THÔNG TIN ĐƠN HÀNG TRA CỨU ĐƯỢC] cho khách.' : 'Yêu cầu khách hàng cung cấp ĐẦY ĐỦ số điện thoại VÀ mã đơn hàng để tra cứu (nếu khách chưa cung cấp đủ).',
 general: 'Trò chuyện lịch sự. Hỏi khách đang quan tâm môn thể thao nào.',
};
const guide = intentGuide[ctx.intent] || intentGuide.general;

let rule2 = '';
let rule3 = '';

if (['stock', 'price', 'describe', 'brand', 'compare'].includes(ctx.intent)) {
  rule2 = '2. NẾU KHÁCH HỎI VỀ MỘT SẢN PHẨM NHƯNG [SẢN PHẨM] TRỐNG → Tuyệt đối không đoán thông tin, MÀ PHẢI TRẢ LỜI: "Xin lỗi bạn, hiện tại mình chưa có thông tin về sản phẩm này..."\n';
}

if (['exchange', 'size', 'shipping', 'payment', 'warranty'].includes(ctx.intent)) {
  rule3 = '3. NẾU KHÁCH HỎI CHÍNH SÁCH NHƯNG [CHÍNH SÁCH] TRỐNG → "Bạn vui lòng liên hệ hotline nhé!"\n';
}

if (ctx.intent === 'general') {
  rule2 = '2. NẾU KHÁCH HỎI VỀ SẢN PHẨM NHƯNG KHÔNG RÕ RÀNG → Trả lời lịch sự và xin thêm thông tin.\n';
}

const prompt =
`Bạn là AI tư vấn viên của TheXuong Sport Store. Tên bạn là TheXuong AI.

===LUẬT TUYỆT ĐỐI (CẤM VI PHẠM)===
0. CHỈ ĐƯỢC PHÉP TRẢ LỜI BẰNG TIẾNG VIỆT (VIETNAMESE). TUYỆT ĐỐI KHÔNG SỬ DỤNG TIẾNG TRUNG QUỐC (CHINESE), KHÔNG DÙNG CÁC TỪ NHƯ 吗, 呢, 吧...
1. KHÔNG TỰ BỊA ĐẶT THÔNG TIN. Chỉ dùng dữ liệu bên dưới.
${rule2}${rule3}4. Dùng ngôn từ tự nhiên, súc tích (dưới 80 từ). Dùng emoji lịch sự.
5. Hướng dẫn riêng cho câu này: ${guide}

===DỮ LIỆU ĐƯỢC CẤP===
${dataBlock || '(Trống)'}
=======================

${historyStr}Khách (${ctx.userName}): ${ctx.userMessage}
Tư vấn viên:`;

return [{
 json: {
 chatId: ctx.chatId,
 userName: ctx.userName,
 userMessage: ctx.userMessage,
 intent: ctx.intent,
 timestamp: ctx.timestamp,
 requestBody: {
 model: "qwen2.5:3b",
 prompt: prompt,
 stream: false,
    think: false,
 options: {
 temperature: 0.1,
 top_p: 0.85,
 num_predict: 600,
 repeat_penalty: 1.2,
 }
 },
 }
}];

const ollamaResp = ($json.response || '').trim();
const buildCtx = $('Build Prompt').item.json;

const botReply = ollamaResp ||
  'Xin lỗi, hệ thống đang bận. Vui lòng thử lại sau! 🙏';

const history = buildCtx.conversationHistory || [];
history.push({ user: buildCtx.userMessage, bot: ollamaResp });
const updatedHistory = history.slice(-5);

return [{
  json: {
    chatId: buildCtx.chatId,
    userName: buildCtx.userName,
    userMessage: buildCtx.userMessage,
    intent: buildCtx.intent,
    botReply: botReply,
    botReplyRaw: ollamaResp,
    updatedHistory: updatedHistory,
    timestamp: buildCtx.timestamp,
  }
}];

const d = $json;
const historyJson = JSON.stringify(d.updatedHistory);
const now = new Date().toISOString();

return [{
 json: {
 chatId: d.chatId,
 userName: d.userName,
 userMessage: d.userMessage,
 intent: d.intent,
 botReply: d.botReplyRaw,
 timestamp: d.timestamp,
 historyJson: historyJson,
 updatedAt: now,
 payloadSave: { chatId: String(d.chatId), historyJson: historyJson },
 payloadLog: { chatId: String(d.chatId), userName: d.userName, intent: d.intent, userMessage: d.userMessage, botReply: d.botReplyRaw }
 }
}];
